  // lib/chains.ts
  var LEGACY_CHAINS = chains_default;
  var EXTRA_CHAINS = chains_extra_default;
  var CHAINS = [...LEGACY_CHAINS, ...EXTRA_CHAINS];
  function countLabel(n) {
    return n < 100 ? String(n) : `${Math.floor(n / 100) * 100}+`;
  }
